when CLIENT_ACCEPTED {
   if { [IP::addr [IP::client_addr] equals 10.10.10.10] } {
      pool my_pool
   }
}

when HTTP_REQUEST {
    switch [IP::addr [IP::client_addr] mask 255.255.255.0] {
        "10.10.4.0" -
        "192.168.4.0" {
            pool pool_http_server_1
        }
        default {
            reject
        }
    }
}
